        // XDG_CONFIG_HOME is the parent of the `agent-runner` directory.
        let xdg = user_file
            .parent()
            .expect("agent-runner dir")
            .parent()
            .expect("xdg dir");
        let env = env_map(vec![("XDG_CONFIG_HOME", str_of(xdg))]);
        let resolved = resolve_config_path_with(
            None,
