        // Remove the local file so the XDG user config is the first hit.
        let _ = std::fs::remove_file(&local_file);
        let xdg = user_file
            .parent()
            .expect("agent-runner dir")
            .parent()
            .expect("xdg dir");
        let env = env_map(vec![("XDG_CONFIG_HOME", str_of(xdg))]);
