        let env = env_map(vec![("HOME", str_of(root.path()))]);
        let err = resolve_config_path_with(None, Some(empty), env)
            .expect_err("no config anywhere must fail");
        let conventional = root
            .path()
            .join(".config")
            .join("agent-runner")
            .join("config.toml")
            .display()
            .to_string();
        assert!(
            err.contains(&conventional),
