        let mut app = app();
        // First sample: establishes the growth baseline.
        app.push_event(Event::Progress {
            input_tokens: 0,
            output_tokens: 0,
            context_tokens: 3000,
            context_limit: 8192,
            context_utilization: 0.4,
            compaction_progress: 0.3,
            tokens_per_sec: 50.0,
            total_tokens: 1024,
            elapsed_secs: 10.0,
        });
        // Second sample, 10s later: 1000 tokens added => 100 tok/s.
        app.push_event(Event::Progress {
            input_tokens: 0,
            output_tokens: 0,
            context_tokens: 4000,
            context_limit: 8192,
            context_utilization: 0.5,
            compaction_progress: 0.45,
            tokens_per_sec: 50.0,
            total_tokens: 2048,
            elapsed_secs: 20.0,
        });
        let eta = app.stats.unwrap().eta_secs;
        // 4192 tokens remain at 100 tok/s => ~42s.
        let secs = eta.expect("an ETA should be forecast while climbing");
        assert!((40.0..44.0).contains(&secs), "eta was {secs}");
    }

    #[test]
    fn eta_is_none_when_growth_is_flat() {
        let mut app = app();
        let push = |app: &mut App, ctx: usize, elapsed: f64| {
            app.push_event(Event::Progress {
                input_tokens: 0,
                output_tokens: 0,
                context_tokens: ctx,
                context_limit: 8192,
                context_utilization: 0.5,
                compaction_progress: 0.4,
                tokens_per_sec: 50.0,
                total_tokens: 1024,
                elapsed_secs: elapsed,
            });
        };
        push(&mut app, 4000, 10.0);
        push(&mut app, 4000, 20.0);
        assert_eq!(app.stats.unwrap().eta_secs, None);
    }

    #[test]
    fn eta_is_none_after_a_compaction_reset() {
        let mut app = app();
        let push = |app: &mut App, ctx: usize, elapsed: f64| {
            app.push_event(Event::Progress {
                input_tokens: 0,
                output_tokens: 0,
                context_tokens: ctx,
                context_limit: 8192,
                context_utilization: 0.5,
                compaction_progress: 0.4,
                tokens_per_sec: 50.0,
                total_tokens: 1024,
                elapsed_secs: elapsed,
            });
        };
        push(&mut app, 4000, 10.0);
        // A compaction rolled the context back down.
        push(&mut app, 2500, 20.0);
        assert_eq!(app.stats.unwrap().eta_secs, None);
    }

    #[test]
    fn eta_suffix_appears_in_stats_line_only_when_climbing() {
        let mut app = app_at(60);
        let push = |app: &mut App, ctx: usize, elapsed: f64| {
            app.push_event(Event::Progress {
                input_tokens: 0,
                output_tokens: 0,
                context_tokens: ctx,
                context_limit: 8192,
                context_utilization: 0.5,
                compaction_progress: 0.4,
                tokens_per_sec: 50.0,
                total_tokens: 1024,
                elapsed_secs: elapsed,
            });
        };
        push(&mut app, 6292, 10.0);
        assert!(!app.stats_line().contains("(in"));
        // 100s later: 1000 tokens added => 10 tok/s; 900 remain => 90s ETA.
        push(&mut app, 7292, 110.0);
        assert!(app.stats_line().contains("(in 1m30s"));
    }

    #[test]
    fn wrap_keeps_fitting_words_on_one_line() {
        // Regression: a previously broken append path replaced the accumulated
        // line with each new word, collapsing a sentence to its last word.
        assert_eq!(
            super::wrap("one two three", 20),
            vec!["one two three".to_owned()]
        );
    }

    #[test]
    fn wrap_wraps_when_a_line_overflows() {
        let rendered = super::wrap("alpha beta gamma", 10);
        assert_eq!(rendered, vec!["alpha beta".to_owned(), " gamma".to_owned()]);
    }

    #[test]
    fn narrower_width_rewraps_the_transcript_into_more_lines() {
        // Same content at two widths: the narrower view must wrap into more
        // transcript rows. Using two independent apps avoids confounding the
        // init note and re-wrap with a resize measurement.
        let mut wide = app();
        let mut narrow = app();
        narrow.resize(20, 24);
        let text = "alpha beta gamma delta epsilon zeta eta theta iota kappa".to_owned();
        wide.push_event(Event::Text(text.clone()));
        wide.flush_pending_text();
        narrow.push_event(Event::Text(text));
        narrow.flush_pending_text();
        let wide_lines = wide.line_count();
        let narrow_lines = narrow.line_count();
        assert!(
            narrow_lines > wide_lines,
            "a narrower width should rewrap into more lines (wide={wide_lines}, narrow={narrow_lines})"
        );
    }

    #[test]
    fn streamed_reasoning_concatenates_into_flowing_lines() {
        // Regression: each reasoning delta used to wrap into its own row, so
        // thinking broke into one short line per fragment.
        let mut app = app();
        let before = app.lines.len();
        for frag in ["The ", "quick ", "brown ", "fox"] {
            app.push_event(Event::Reasoning(frag.to_owned()));
        }
        // Still pending: no blank line to flush a reasoning paragraph yet.
        assert_eq!(app.lines.len(), before);
        // A non-reasoning event flushes the accumulated reasoning, concatenated.
        app.push_event(Event::Finished {
            message: "done".to_owned(),
        });
        let reasoning: Vec<&str> = app
            .lines
            .iter()
            .filter(|line| line.kind == LineKind::Reasoning)
            .map(|line| line.text.as_str())
            .collect();
        assert!(
            reasoning.contains(&"The quick brown fox"),
            "reasoning should concatenate horizontally, not one row per delta:\n{:?}",
            app.lines.iter().map(|l| &l.text).collect::<Vec<_>>()
        );
    }

    #[test]
    fn auto_follows_new_output_to_the_bottom() {
        // By default the transcript is pinned to the newest line: appending far
        // more rows than fit must keep the view at the bottom.
        let mut app = app();
        assert!(app.following);
        for i in 0..50 {
            app.push_event(Event::Note(format!("line {i}")));
        }
        assert_eq!(app.scroll, app.bottom_offset());
        assert!(app.following);
    }

    #[test]
    fn scrolling_unpins_and_stays_put() {
        let mut app = app();
        for i in 0..50 {
            app.push_event(Event::Note(format!("line {i}")));
        }
        assert_eq!(app.scroll, app.bottom_offset());
        // Scroll up to read older output: auto-follow must unpin.
        app.scroll_up(10);
        assert!(!app.following);
        let pinned = app.scroll;
        // New output arrives; the view must not jump back down.
        app.push_event(Event::Note("newest line".to_owned()));
        assert_eq!(app.scroll, pinned);
        assert!(!app.following);
    }

    #[test]
    fn ctrl_end_refollows_to_the_bottom() {
        let mut app = app();
        for i in 0..50 {
            app.push_event(Event::Note(format!("line {i}")));
        }
        app.scroll_up(15);
        assert!(!app.following);
        let above_bottom = app.scroll;
        assert!(above_bottom < app.bottom_offset());
        // Ctrl+End jumps to the newest output and resumes auto-follow.
        app.on_key(ctrl(KeyCode::End));
        assert_eq!(app.scroll, app.bottom_offset());
        assert!(app.following);
    }
}

//! Process entry point for the `agent-runner` binary.
//!
//! Logging initialisation, configuration resolution, and dispatch to the
//! interactive terminal UI. All logic lives in the `agent_runner` library;
//! this binary only wires the CLI to it and maps failures to exit codes.

use std::path::Path;
use std::process::ExitCode;

use agent_runner::{Cli, ToolProfile, config::Config, init_logging, tui, tui::Overrides};
use clap::Parser;

fn main() -> ExitCode {
    init_logging();
    match run() {
        Ok(code) => code,
        Err(message) => {
            eprintln!("{message}");
            ExitCode::from(2)
        }
    }
}

fn run() -> std::result::Result<ExitCode, String> {
    let cli = Cli::parse();

    // Importing Kvist agent profiles is a read-only, non-interactive command
    // that does not need an agent-runner configuration.
    if cli.import_kvist {
        return import_kvist(cli.kvist_config.clone());
    }

    // Resolve the configuration once so both `--config` and `--list-models`
    // share the same discovery rules and error messages.
    let config_path = agent_runner::resolve_config_path(cli.config.clone())?;

    // Listing configured models is a read-only, non-interactive command.
    if cli.list_models {
        return list_models(&config_path);
    }

    let config = Config::load(&config_path).map_err(|error| error.describe())?;

    let effort = match &cli.effort {
        Some(value) => Some(agent_runner::parse_effort(value)?),
        None => None,
    };
    let profile = match &cli.profile {
        Some(name) => Some(ToolProfile::from_id(name).ok_or_else(|| {
            format!("unknown tool profile `{name}`; expected generic, rust, or python")
        })?),
        None => None,
    };

    let overrides = Overrides {
        model: cli.model.clone(),
        effort,
        cwd: cli.cwd.clone(),
        profile,
        log_dir: cli.log_dir.clone(),
        context_limit: cli.context_limit,
        no_logs: cli.no_logs,
        config_path: Some(config_path.clone()),
    };

    Ok(tui::run(config, overrides))
}

/// Prints `[[models]]` entries derived from a Kvist project configuration so
/// the project's agents can be reused in the agent-runner configuration.
fn import_kvist(kvist_config: Option<std::path::PathBuf>) -> std::result::Result<ExitCode, String> {
    let path = agent_runner::resolve_kvist_config_path(kvist_config)?;
    let snippet = agent_runner::import_models(&path).map_err(|error| error.describe())?;
    println!("# imported from {}", path.display());
    print!("{snippet}");
    Ok(ExitCode::SUCCESS)
}

fn list_models(config_path: &Path) -> std::result::Result<ExitCode, String> {
    let config = Config::load(config_path).map_err(|error| error.describe())?;

    println!("configured models:");
    if config.models.is_empty() {
        println!("  (none)");
    } else {
        for model in &config.models {
            println!(
                "  {:<12} {:<12?} {}  {}  (deadline {}s)",
                model.id, model.provider, model.base_url, model.model, model.deadline_secs
            );
        }
    }
    println!("\ndefault model: {}", config.default_model);
    Ok(ExitCode::SUCCESS)
}

//! Rendering for the terminal UI.

use ratatui::layout::{Alignment, Constraint, Rect};
use ratatui::style::{Color, Style};
use ratatui::text::{Line, Span, Text};
use ratatui::widgets::{Block, Borders, Paragraph};

use super::app::App;

/// Rows reserved for the multiline prompt editor around the transcript.
const INPUT_ROWS: u16 = 4;

/// Renders one frame of the application.
pub fn render(f: &mut ratatui::Frame, app: &App) {
    let area = f.area();
    let vertical = ratatui::layout::Layout::vertical([
        Constraint::Length(1),
        Constraint::Length(1),
        Constraint::Min(1),
        Constraint::Length(INPUT_ROWS),
    ]);
    let areas = vertical.split(area);
    let mut split = areas.iter();
    let header_area = *split.next().expect("header area");
    let stats_area = *split.next().expect("stats area");
    let transcript_area = *split.next().expect("transcript area");
    let input_area = *split.next().expect("input area");

    render_header(f, app, header_area);
    render_stats(f, app, stats_area);
    if app.show_help {
        render_help(f, app, transcript_area);
    } else {
        render_transcript(f, app, transcript_area);
    }
    render_input(f, app, input_area);
}

/// The live stats bar: working speed, context utilization, and compaction
/// progress. Shown even before the first turn so the overview is always present.
fn render_stats(f: &mut ratatui::Frame, app: &App, area: Rect) {
    let stats_text = app.stats_line();
    let text = if stats_text.is_empty() {
        " ⚡ — tok/s   context —    ·   compaction — ".to_owned()
    } else {
        stats_text
    };
    let block = Block::default()
        .borders(Borders::BOTTOM)
        .title(Span::styled(
            " stats ",
            Style::default().fg(Color::DarkGray),
        ));
    let paragraph = Paragraph::new(Line::from(Span::styled(
        text,
        Style::default().fg(Color::Green),
    )))
    .block(block);
    f.render_widget(paragraph, area);
}

fn render_header(f: &mut ratatui::Frame, app: &App, area: Rect) {
    let running = if app.running { " · running" } else { "" };
    let title = format!(
        " agent-runner  ·  model: {}  ·  thinking: {}  ·  status: {}{}",
        highlight(&app.model, app.running),
        app.effort.as_str(),
        app.status,
        running
    );
    let block = Block::default()
        .borders(Borders::BOTTOM)
        .title(Span::styled(title, Style::default().fg(Color::Cyan).bold()));
    f.render_widget(block, area);
}

fn render_transcript(f: &mut ratatui::Frame, app: &App, area: Rect) {
    let lines: Vec<Line> = app
        .lines
        .iter()
        .map(|screen_line| Line::from(Span::styled(screen_line.text.clone(), screen_line.style)))
        .collect();
    let block = Block::default().borders(Borders::ALL).title(Span::styled(
        format!(" transcript [{}] ", app.lines.len()),
        Style::default().fg(Color::DarkGray),
    ));
    let paragraph = Paragraph::new(Text::from(lines))
        .block(block)
        .scroll((app.scroll, 0));
    f.render_widget(paragraph, area);
}

fn render_input(f: &mut ratatui::Frame, app: &App, area: Rect) {
    f.render_widget(&app.editor, area);
    // The editor reports the terminal-relative cursor position from the most
    // recent render; park the real terminal cursor there so typing is visible.
    if let Some(position) = app.editor.rendered_cursor_position() {
        f.set_cursor_position(position);
    }
}

fn render_help(f: &mut ratatui::Frame, app: &App, area: Rect) {
    let config_path = app
        .config_path
        .as_ref()
        .map(|path| path.to_string_lossy().into_owned())
        .unwrap_or_else(|| "(none found)".to_owned());
    let config_hint = format!(
        "  {} models are configured; Tab / Shift+Tab switch model and effort per prompt.",
        app.models.len()
    );
    let lines = vec![
        Line::from(Span::styled(
            "agent-runner help",
            Style::default().fg(Color::Cyan).bold(),
        )),
        Line::from(""),
        Line::from("  Ctrl+Enter       submit the prompt"),
        Line::from("  Enter            submit on a blank line, else a newline"),
        Line::from("  Shift+Enter      always insert a blank line"),
        Line::from("  Tab / Shift+Tab  next model / next thinking effort (per prompt)"),
        Line::from("  Ctrl+P / Ctrl+N  previous / next prompt history"),
        Line::from("  Ctrl+C           cancel a running turn, or quit when idle"),
        Line::from("  Ctrl+D           quit when the prompt is empty"),
        Line::from("  PageUp / PageDown scroll the transcript"),
        Line::from("  Ctrl+L           clear the transcript"),
        Line::from("  Ctrl+T           collapse/reveal reasoning in the transcript"),
        Line::from("  Ctrl+H / Esc     toggle this help"),
        Line::from(""),
        Line::from("  The top bar shows model, thinking effort, and status."),
        Line::from(""),
        Line::from("  Configuration (add agents / models here):"),
        Line::from(format!("    {config_path}")),
        Line::from("    Add a [[models]] entry: id, provider (llama-server or"),
        Line::from("    ollama), base_url, provider model name, deadline_secs."),
        Line::from("    Reuse agents declared in Kvist's kvist.toml:"),
        Line::from("    agent-runner --import-kvist  (prints [[models]] to paste)."),
        Line::from(config_hint),
        Line::from(""),
        Line::from("  The stats bar shows: working speed (tok/s), context"),
        Line::from("  utilization of the model window, and how close we are to"),
        Line::from("  an automatic compaction. A compaction 'in ...' ETA is"),
        Line::from("  shown while the live context steadily climbs toward the"),
        Line::from("  limit; it is suppressed when the context is flat or was"),
        Line::from("  just rolled back by a compaction, so the number is honest"),
        Line::from(""),
        Line::from("  Compaction keeps the model's context bounded by rolling"),
        Line::from("  older turns into a summary. Full reasoning is always"),
        Line::from("  saved to the session journal + transcript; Ctrl+T only"),
        Line::from("  hides it in the live view. The agent runs inside the"),
        Line::from("  sandbox. Writes stay inside the working directory."),
    ];
    let block = Block::default().borders(Borders::ALL).title(Span::styled(
        " help",
        Style::default().fg(Color::Cyan).bold(),
    ));
    // Clamp the scroll to the rendered content so a short terminal never shows
    // a blank box: the help is taller than the transcript box, so it scrolls,
    // but the offset must stay within the help's own lines.
    let content_height = lines.len() as u16;
    let inner_height = area.height.saturating_sub(2).max(1);
    let scroll = app
        .help_scroll
        .min(content_height.saturating_sub(inner_height));
    let paragraph = Paragraph::new(Text::from(lines))
        .block(block)
        .alignment(Alignment::Left)
        .scroll((scroll, 0));
    f.render_widget(paragraph, area);
}

fn highlight(text: &str, active: bool) -> Span<'static> {
    Span::styled(
        text.to_owned(),
        if active {
            Style::default().fg(Color::Yellow).bold()
        } else {
            Style::default().fg(Color::Green)
        },
    )
}

#[cfg(test)]
